    $bDec = function ($k, $lo, $hi, $label) { $v = (string) ($_POST[$k] ?? ''); if (!preg_match('/^\d+(\.\d{1,3})?$/', $v) || (float) $v < $lo || (float) $v > $hi) beta_av_fail("$label must be from $lo to $hi."); };
